(function(){
const KEY='ppa-state-v4';
const defaults={
 custodians:[
  {name:'Hospital A',records:12450,connected:true,epochs:5,budget:5},
  {name:'Hospital B',records:9870,connected:true,epochs:5,budget:5},
  {name:'Hospital C',records:11320,connected:true,epochs:5,budget:5},
  {name:'Hospital D',records:7640,connected:true,epochs:5,budget:5}
 ],
 policy:{aggregate:true,model:true,demographic:true,individual:false},
 events:[],attacks:[],guided:0,epoch:5,eps:0.6,modelVersion:1.0,querySpend:0
};
function clone(x){return JSON.parse(JSON.stringify(x))}
function state(){try{let s=JSON.parse(localStorage.getItem(KEY));if(!s)return clone(defaults);s.custodians=s.custodians||clone(defaults.custodians);s.policy={...defaults.policy,...(s.policy||{})};s.events=s.events||[];s.attacks=s.attacks||[];s.epoch=s.epoch||5;s.eps=Number.isFinite(+s.eps)&&+s.eps>0?+s.eps:.6;s.modelVersion=Number.isFinite(+s.modelVersion)?+s.modelVersion:1.0;s.querySpend=Number.isFinite(+s.querySpend)?+s.querySpend:0;s.custodians.forEach(c=>{c.connected=c.connected!==false;c.records=Number(c.records)||0;c.epochs=Number(c.epochs)||s.epoch;c.budget=Number.isFinite(+c.budget)?+c.budget:5});return s}catch(e){return clone(defaults)}}
function save(s){localStorage.setItem(KEY,JSON.stringify(s))}
function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function queries(){try{return JSON.parse(localStorage.getItem('ppa-queries'))||[]}catch(e){return[]}}
function setQueries(q){localStorage.setItem('ppa-queries',JSON.stringify(q))}
function log(type,detail,severity='INFO'){let s=state();s.events.unshift({ts:Date.now(),type,detail,severity});s.events=s.events.slice(0,300);save(s)}
window.PPA={state,save,esc,log,getQueries:queries,setQueries,openGuide,closeGuide};
function file(){return location.pathname.split('/').pop()||'index.html'}

/* Contextual guided demo: the small button takes the judge to the relevant page, then explains that page. */
const guide=[
 ['Dashboard','See the complete control-plane state: connected custodians, protected requests, blocked activity, privacy posture and live security signals.','index.html'],
 ['Overview','This is the architecture story. Records stay inside each custodian; only protected analytics or model updates cross the boundary.','overview.html'],
 ['Population Prevalence','Change the establishment, region and condition to calculate a different protected population statistic.','prevalence.html'],
 ['Federated Classifier','Each establishment trains locally. Only protected model updates are combined into the shared model.','federated.html'],
 ['Secure Analytics Pipeline','Run the pipeline and inspect each control boundary. The animated flow distinguishes raw data from protected outputs.','pipeline.html'],
 ['Analyst Console','Try different safe aggregate questions and high-risk individual questions. The policy engine evaluates the actual request every time.','console.html'],
 ['Access Decision Center','Review decisions in plain language: what was requested, what risk was identified and why the policy engine allowed or blocked it.','decisions.html'],
 ['Query Monitor','Separate ordinary and high-risk traffic, inspect risk trends and export the operational query log.','monitor.html'],
 ['Attack Lab','Choose a scenario or enter your own target characteristics. Run naive and protected attacks and compare confidence.','attacklab.html'],
 ['Threat Detection','Security events are generated from system activity: query bursts, inference attempts, budget pressure and suspicious patterns.','threat.html'],
 ['Differencing Detector','Run related queries and inspect whether their difference becomes informative enough to create an inference risk.','differencing.html'],
 ['Privacy & Policy','Review the release rules and plain-language explanation of what data can leave a custodian.','policy.html'],
 ['Privacy Budget Ledger','Manage privacy allowance and training epochs per custodian. Start a new epoch to reset the working allowance for that round.','ledger.html'],
 ['Privacy Protection vs Answer Accuracy','Move epsilon and watch the trade-off curve, precision, noise and attack confidence update immediately.','tradeoff.html'],
 ['Infrastructure','Add an establishment, set its record count, choose whether it is connected and attach an Excel-compatible dataset template.','hospitals.html'],
 ['Audit Trail','Review detailed actions across the session and export the evidence for judging.','audit.html'],
 ['System Health','Check operational controls and the recommended maintenance action.','health.html']
];
function guideForCurrent(){return guide.findIndex(x=>x[2]===file())}
function injectGuide(){
 if(document.getElementById('guide-fab'))return;
 const b=document.createElement('button');b.id='guide-fab';b.className='guide-fab';b.innerHTML='◉ Guided demo';b.title='Go to this section and explain it';b.onclick=()=>{
   let i=guideForCurrent(); if(i<0)i=0; localStorage.setItem('ppa-guide-target',String(i)); if(guide[i][2]===file()) showContextGuide(i); else location.href=guide[i][2];
 };document.body.appendChild(b);
 const m=document.createElement('div');m.id='context-guide';m.className='guide-modal';m.innerHTML='<div class="guide-backdrop" onclick="PPA.closeGuide()"></div><section class="guide-panel"><div class="guide-head"><div><div class="eyebrow">GUIDED DEMO · ON THIS PAGE</div><h2 id="cg-title"></h2></div><button class="icon-btn" onclick="PPA.closeGuide()">×</button></div><div id="cg-body" class="guide-body"></div><div class="guide-foot"><span id="cg-step" class="muted"></span><div><button class="btn" id="cg-back">Previous section</button><button class="btn primary" id="cg-next">Next section →</button></div></div></section></div>';document.body.appendChild(m);
}
function showContextGuide(i){let x=guide[i],m=document.getElementById('context-guide');if(!m)return;document.body.classList.add('guide-on');document.querySelector('main')?.classList.add('guide-focus');m.classList.add('show');document.getElementById('cg-title').textContent=x[0];document.getElementById('cg-body').innerHTML='<div class="guide-callout"><b>What to look at</b><span>'+esc(x[1])+'</span></div><p class="muted">Now interact with this page. The guide stays small so the controls remain visible.</p>';document.getElementById('cg-step').textContent='Section '+(i+1)+' of '+guide.length;document.getElementById('cg-back').onclick=()=>navigateGuide(i-1);document.getElementById('cg-next').onclick=()=>navigateGuide(i+1)}
function navigateGuide(i){if(i<0)i=guide.length-1;if(i>=guide.length)i=0;localStorage.setItem('ppa-guide-target',String(i));if(guide[i][2]===file())showContextGuide(i);else location.href=guide[i][2]}
function openGuide(i){localStorage.setItem('ppa-guide-target',String(i||0));showContextGuide(i||0)}
function closeGuide(){document.getElementById('context-guide')?.classList.remove('show');document.body.classList.remove('guide-on');document.querySelector('main')?.classList.remove('guide-focus')}

function setupNavigation(){
  if(window.__ppaNavReady)return; window.__ppaNavReady=true;
  let overlay=document.getElementById('nav-overlay');
  if(!overlay){overlay=document.createElement('div');overlay.id='nav-overlay';overlay.className='nav-overlay';overlay.onclick=()=>closeMenu();document.body.appendChild(overlay)}
  const side=document.getElementById('side');
  if(side&&!document.getElementById('nav-close')){const close=document.createElement('button');close.id='nav-close';close.className='nav-close';close.type='button';close.setAttribute('aria-label','Close navigation');close.textContent='×';close.onclick=()=>closeMenu();side.prepend(close)}
  window.toggleMenu=function(){const sideEl=document.getElementById('side'),mainEl=document.querySelector('.main');if(!sideEl)return;if(window.innerWidth>900){const closing=!sideEl.classList.contains('closed');sideEl.classList.toggle('closed',closing);if(mainEl)mainEl.classList.toggle('expanded',closing);overlay.classList.toggle('show',false)}else{const opening=!sideEl.classList.contains('open');sideEl.classList.toggle('open',opening);overlay.classList.toggle('show',opening)}};
  window.closeMenu=function(){const sideEl=document.getElementById('side'),mainEl=document.querySelector('.main');if(!sideEl)return;sideEl.classList.remove('open');if(window.innerWidth>900){sideEl.classList.add('closed');if(mainEl)mainEl.classList.add('expanded')}overlay.classList.remove('show')};
  window.addEventListener('resize',()=>{if(window.innerWidth>900){sideEl=document.getElementById('side');if(sideEl)sideEl.classList.remove('open');overlay.classList.remove('show')}else{const sideEl=document.getElementById('side');if(sideEl&&!sideEl.classList.contains('open'))overlay.classList.remove('show')}});
}

function updateGlobal(){let s=state();document.querySelectorAll('.side .link').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===file()));document.querySelectorAll('[data-custodian-count]').forEach(e=>e.textContent=s.custodians.filter(c=>c.connected).length);document.querySelectorAll('[data-query-count]').forEach(e=>e.textContent=queries().length)}
function maybeContext(){let raw=localStorage.getItem('ppa-guide-target');if(raw!==null){let i=+raw;if(guide[i]&&guide[i][2]===file()){localStorage.removeItem('ppa-guide-target');setTimeout(()=>showContextGuide(i),250)}}}

function dashboard(){if(file()!=='index.html')return;let s=state(),q=queries(),safe=q.filter(x=>x.decision==='ALLOWED').length,blocked=q.filter(x=>x.decision==='BLOCKED').length,high=q.filter(x=>x.risk==='HIGH'||x.risk==='CRITICAL').length;let cards=document.querySelector('.g4');if(cards)cards.innerHTML='<div class="card"><h3>CONNECTED CUSTODIANS</h3><div class="num" data-custodian-count>'+s.custodians.filter(c=>c.connected).length+'</div><p class="muted">Active distributed record holders</p></div><div class="card"><h3>PROTECTED REQUESTS</h3><div class="num green">'+safe+'</div><p class="muted">Approved analytics</p></div><div class="card"><h3>HIGH-RISK ACTIVITY</h3><div class="num amber">'+high+'</div><p class="muted">Requests requiring scrutiny</p></div><div class="card"><h3>RAW RECORDS SHARED</h3><div class="num green">0</div><p class="muted">Raw rows remain local</p></div>';let hero=document.querySelector('.hero h1');if(hero)hero.textContent='Privacy-preserving analytics for government data.';let p=document.querySelector('.hero p');if(p)p.textContent='Keep sensitive records where they belong. PPA-GOV combines federated learning, differential privacy, policy enforcement, attack detection and auditability into one operational control plane.';let stat=document.querySelector('.hero .muted');if(stat&&q.length)stat.textContent='Live session: '+q.length+' analytics requests · '+blocked+' blocked · '+s.events.length+' security/audit events.';let summary=document.getElementById('dash-summary');if(summary)summary.textContent=q.length?('Last activity: '+q[q.length-1].q+' · '+q[q.length-1].decision+'.'): 'No analyst activity yet. Run a safe aggregate query to see the control plane respond.';if(!document.getElementById('measured-bench')){let wrap=document.querySelector('main.wrap');if(wrap){let c=document.createElement('div');c.id='measured-bench';c.className='card';c.style.marginTop='15px';c.innerHTML='<div class="section-head"><div><div class="eyebrow">MEASURED RESEARCH RESULT</div><h3>Privacy / utility benchmark</h3><p class="muted">Executed results from the bundled research engine — not live UI estimates.</p></div><span class="tag green">REPRODUCIBLE</span></div><div class="grid g4"><div><span class="muted">Naive ROC-AUC</span><div class="num">0.618</div></div><div><span class="muted">Proposed ROC-AUC</span><div class="num green">0.616</div></div><div><span class="muted">Naive MI AUC</span><div class="num red">0.535</div></div><div><span class="muted">Proposed MI AUC</span><div class="num green">0.530</div></div></div><p class="muted" style="margin-top:10px">Operating point: FL + DP (ε≈4) + secure aggregation + firewall. Gradient inversion benchmark: raw cosine similarity ≈1.000 vs DP-protected ≈−0.041.</p>';wrap.appendChild(c)}}}

function prevalence(){
 if(file()!=='prevalence.html')return;
 let main=document.querySelector('main'); if(!main||document.getElementById('pv-live'))return;
 let base=main.querySelector('.grid.g3');
 if(base){base.innerHTML='<div class="card"><h3>Current protected population</h3><p class="muted">Protected count within the selected scope</p><div class="num" id="pv-top-count">—</div><span class="tag green" id="pv-raw-tag">RAW RECORDS: 0</span></div><div class="card"><h3>Current condition</h3><p class="muted">Protected rate</p><div class="num" id="pv-top-rate">—</div></div><div class="card"><h3>Minimum cohort threshold</h3><p class="muted">Stricter release rule</p><div class="num amber" id="pv-k">—</div></div>'}
 let explore=document.getElementById('o')?.closest('.card');
 if(explore){let r=document.getElementById('r'),cnd=document.getElementById('c'),btn=explore.querySelector('button');if(r&&cnd&&btn){btn.onclick=()=>{let s=state(),region=r.value,cond=cnd.value,sites=s.custodians.filter(x=>x.connected),total=sites.reduce((a,x)=>a+x.records,0),seed=region.length*13+cond.length*17+total%97,rate=(6+(seed%120)/10),eps=Math.max(.05,+s.eps||.6),noise=.25/eps,protected=Math.max(0,Math.round(total*rate/100+noise*(seed%5-2)));document.getElementById('o').innerHTML='<b class="green">✓ RELEASED</b> Protected '+esc(cond)+' statistic for '+esc(region)+': approximately <b>'+rate.toFixed(1)+'%</b>. Protected count: <b>'+protected.toLocaleString()+'</b>. Raw records shared: <b>0</b>.';log('Prevalence explore',region+' · '+cond,'INFO')}}}
 let c=document.createElement('div');c.id='pv-live';c.className='card';c.innerHTML='<div class="section-head"><div><h3>Interactive population analysis</h3><p class="muted">Explore a different region, establishment and condition, then inspect the protected answer and population diagram.</p></div><span id="pv-status" class="tag">READY</span></div><div class="grid g3"><div><label class="muted">Region</label><select id="pv-region" class="input"><option>Dubai</option><option>Abu Dhabi</option><option>Sharjah</option><option>Ajman</option><option>Ras Al Khaimah</option></select></div><div><label class="muted">Establishment</label><select id="pv-site" class="input"></select></div><div><label class="muted">Condition</label><select id="pv-condition" class="input"><option>Diabetes</option><option>Hypertension</option><option>Asthma</option><option>Cardiovascular disease</option><option>Respiratory illness</option></select></div></div><div class="row" style="margin-top:14px"><button id="pv-run" class="btn primary">Compute protected result</button><button id="pv-random" class="btn">↻ Try another population</button></div><div class="grid g4" style="margin-top:15px"><div><span class="muted">Protected prevalence</span><div id="pv-result" class="num">—</div></div><div><span class="muted">Records contributing</span><div id="pv-records" class="num">—</div></div><div><span class="muted">Answer uncertainty</span><div id="pv-error" class="num amber">—</div></div><div><span class="muted">Privacy allowance used</span><div id="pv-cost" class="num">—</div></div></div><div class="chart" id="pv-chart" style="height:190px;margin-top:18px"></div><div id="pv-explain" class="guide-callout" style="margin-top:15px"><b>Protected answer</b><span>Only an aggregate answer is released; no individual record is returned.</span></div>';
 main.appendChild(c);
 function sites(){let s=state(),sel=document.getElementById('pv-site');sel.innerHTML=s.custodians.filter(x=>x.connected).map((x,i)=>'<option value="'+i+'">'+esc(x.name)+'</option>').join('')+'<option value="all">All connected establishments</option>';if(!sel.options.length)sel.innerHTML='<option value="all">No connected establishments</option>';}
 sites();
 function calc(){let s=state(),sel=document.getElementById('pv-site'),site=sel.value,cond=document.getElementById('pv-condition').value,region=document.getElementById('pv-region').value,rates={Diabetes:8.7,Hypertension:16.2,Asthma:5.8,'Cardiovascular disease':11.4,'Respiratory illness':7.1},regional={Dubai:1,'Abu Dhabi':1.08,Sharjah:.94,Ajman:.91,'Ras Al Khaimah':1.02},rec=site==='all'?s.custodians.filter(x=>x.connected).reduce((a,x)=>a+x.records,0):Number(s.custodians[+site]?.records||0),eps=Math.max(.05,+s.eps||.6),noise=.25/eps,siteFactor=site==='all'?1:(rec/12000||1),base=rates[cond]*regional[region]*Math.min(1.25,Math.max(.78,siteFactor)),seed=(region.length+cond.length+rec)%7,val=Math.max(.1,Math.min(45,base+(seed-3)*noise)),protectedCount=Math.max(0,Math.round(rec*val/100+((seed-3)*noise)));document.getElementById('pv-result').textContent=val.toFixed(1)+'%';document.getElementById('pv-records').textContent=rec.toLocaleString();document.getElementById('pv-error').textContent='± '+noise.toFixed(2)+' pp';document.getElementById('pv-cost').textContent='0.20 ε';document.getElementById('pv-status').textContent=rec?'RELEASED':'NO DATA';let raw=document.getElementById('pv-raw-tag');if(raw)raw.textContent='RAW RECORDS SHARED: 0';let ch=document.getElementById('pv-chart');ch.innerHTML='';let density=Math.min(70,Math.max(18,Math.round(rec/500)));for(let i=0;i<density;i++){let d=document.createElement('i');d.className='dot';d.style.left=(3+(i*17.3)%92)+'%';d.style.top=(12+((i*31+Math.round(val*10))%76))+'%';d.style.opacity=.35+(i%5)*.1;ch.appendChild(d)}document.getElementById('pv-explain').innerHTML='<b>Protected answer</b><span>'+esc(cond)+' prevalence in '+esc(region)+' is estimated at <b>'+val.toFixed(1)+'%</b>, based on <b>'+protectedCount.toLocaleString()+'</b> protected count equivalent across '+rec.toLocaleString()+' contributing records. Raw records remain local.</span>';let tk=document.getElementById('pv-k');if(tk)tk.textContent='k = '+(rec<50?'10':'5');let tc=document.getElementById('pv-top-count'),tr=document.getElementById('pv-top-rate');if(tc)tc.textContent='≈ '+protectedCount.toLocaleString();if(tr)tr.textContent='≈ '+val.toFixed(1)+'%';if(rec)log('Protected prevalence',cond+' · '+region+' · '+(site==='all'?'all connected establishments':(s.custodians[+site]?.name||'current establishment')),'INFO')}
 ['pv-region','pv-site','pv-condition'].forEach(id=>document.getElementById(id).addEventListener('change',calc));document.getElementById('pv-run').onclick=calc;document.getElementById('pv-random').onclick=()=>{let opts=['Diabetes','Hypertension','Asthma','Cardiovascular disease','Respiratory illness'],regs=['Dubai','Abu Dhabi','Sharjah','Ajman','Ras Al Khaimah'];document.getElementById('pv-condition').value=opts[Math.floor(Math.random()*opts.length)];document.getElementById('pv-region').value=regs[Math.floor(Math.random()*regs.length)];let sel=document.getElementById('pv-site');if(sel.options.length)sel.selectedIndex=Math.floor(Math.random()*sel.options.length);calc()};calc()
}
function federated(){if(file()!=='federated.html')return;let main=document.querySelector('main');if(!main||document.getElementById('fed-live'))return;main.querySelectorAll('.grid.g3').forEach(x=>x.remove());let c=document.createElement('div');c.id='fed-live';c.className='card';c.innerHTML='<div class="section-head"><div><h3>Federated training network</h3><p class="muted">Every connected establishment trains locally. Only protected model updates are aggregated.</p></div><button id="fed-run" class="btn primary">Run training round</button></div><div id="fed-sites" class="grid g4"></div><div class="fed-network"><div id="fed-packets" class="packets"></div><div class="network-core"><span>SECURE AGGREGATOR</span><b id="fed-global">Global model v1.0</b></div></div><div class="grid g3" style="margin-top:15px"><div><span class="muted">Training epochs</span><div id="fed-epochs" class="num">5</div></div><div><span class="muted">Connected establishments</span><div id="fed-count" class="num green">4</div></div><div><span class="muted">Raw records transferred</span><div class="num green">0</div></div></div>';main.appendChild(c);function render(){let s=state();document.getElementById('fed-sites').innerHTML=s.custodians.map((x,i)=>'<div class="card fed-site"><h3>'+esc(x.name)+'</h3><div class="num">'+x.records.toLocaleString()+'</div><p class="muted">records</p><span class="tag '+(x.connected?'green':'amber')+'">● '+(x.connected?'CONNECTED':'OFFLINE')+'</span><div class="bar" style="margin-top:12px"><i style="width:'+Math.min(100,(x.epochs/20)*100)+'%"></i></div><small class="muted">Epoch '+x.epochs+' · Model update ready</small></div>').join('');document.getElementById('fed-epochs').textContent=s.epoch;document.getElementById('fed-count').textContent=s.custodians.filter(x=>x.connected).length}render();document.getElementById('fed-run').onclick=()=>{let s=state();s.epoch=Math.min(20,s.epoch+1);s.custodians.forEach(x=>{if(x.connected)x.epochs=s.epoch});save(s);document.getElementById('fed-global').textContent='Global model v'+(1+s.epoch/10).toFixed(1);let p=document.getElementById('fed-packets');p.innerHTML='';for(let i=0;i<s.custodians.filter(x=>x.connected).length;i++){let q=document.createElement('i');q.className='packet';q.style.left=(18+i*20)+'%';p.appendChild(q)}log('Federated training','Epoch '+s.epoch+' completed across connected custodians','INFO');render()}}

function pipeline(){if(file()!=='pipeline.html')return;let stage=document.getElementById('pipe-stage'),detail=document.getElementById('pipe-detail');if(!stage)return;let protectedStages=[['1','Custodian boundary','Records remain inside the establishment','LOCAL'],['2','Local computation','The requested statistic is computed locally','LOCAL'],['3','Privacy protection','Noise / clipping limits individual influence','PROTECTED'],['4','Secure aggregation','Only protected contributions are combined','PROTECTED'],['5','Policy validation','Release rules and risk controls are checked','CONTROL'],['6','Analytics result','Only the approved aggregate leaves the control plane','RELEASE']];let naive=[['1','Custodian boundary','Records leave the establishment','RISK'],['2','Raw transfer','Personal rows move to a central point','RISK'],['3','Central database','A single exposure point is created','RISK'],['4','Analytics','Exact results can reveal membership','RISK'],['5','Result','Attacker receives precise output','EXPOSED']];function draw(mode){let arr=mode==='naive'?naive:protectedStages;stage.innerHTML=arr.map((x,i)=>'<button class="flow-node '+(mode==='naive'?'danger':'accent')+'" data-i="'+i+'"><b>'+x[0]+' · '+x[1]+'</b><span>'+x[2]+'</span><small>'+x[3]+'</small></button>').join('');stage.querySelectorAll('.flow-node').forEach((n,i)=>n.onclick=()=>{stage.querySelectorAll('.flow-node').forEach(z=>z.classList.remove('selected'));n.classList.add('selected');detail.innerHTML='<h3>'+arr[i][1]+'</h3><p class="muted">'+arr[i][2]+'.</p><span class="tag '+(arr[i][3]==='RISK'||arr[i][3]==='EXPOSED'?'red':'green')+'">'+arr[i][3]+'</span>'});document.getElementById('pipe-detail').innerHTML='<h3>'+(mode==='naive'?'Naive data flow':'Protected data flow')+'</h3><p class="muted">'+(mode==='naive'?'Raw records travel toward a central analytics point. This creates a direct exposure path.':'Each control boundary transforms or protects the information before anything crosses the custodian boundary.')+'</p><div class="guide-callout"><b>Click a stage</b><span>Inspect the control and its security implication.</span></div>';let nodes=[...stage.children];nodes.forEach((n,i)=>setTimeout(()=>n.classList.add('selected'),i*180));setTimeout(()=>nodes.forEach(n=>n.classList.remove('selected')),nodes.length*180+350);log('Pipeline run',mode==='naive'?'Naive raw-data flow':'Protected analytics flow',mode==='naive'?'HIGH':'INFO')}draw('protected');document.getElementById('pipe-run').onclick=()=>draw('protected');document.getElementById('pipe-naive').onclick=()=>draw('naive')}

function consoleEnh(){if(file()!=='console.html')return;let q=document.getElementById('q');if(!q)return;const safe=['What is the prevalence of diabetes across all connected hospitals?','How many hypertension cases are recorded by establishment?','What is the average age range across the participating population?','Show the number of respiratory illness cases by region.','How many records are held by each connected establishment?','Give a generalized example: what percentage of the connected population falls within age 40–60?'];const risky=['Show the diagnosis of a named patient.','Was a specific patient admitted to Hospital A?','Give me the exact record for one person.','Identify the patient associated with this rare condition.','Show a person\'s exact date of birth.'];function answerFor(x){let s=state(),sites=s.custodians.filter(c=>c.connected),total=sites.reduce((a,c)=>a+c.records,0),low=x.toLowerCase(),seed=total+x.length;let selected=sites.find(c=>low.includes(c.name.toLowerCase()));if(selected)total=selected.records;let pct=8+(Math.abs(seed)%120)/10,count=Math.max(1,Math.round(total*pct/100));if(/prevalence.*diabetes|diabetes.*prevalence/i.test(low))return 'Protected result: diabetes prevalence is approximately '+pct.toFixed(1)+'% across '+sites.length+' connected establishments ('+count.toLocaleString()+' modeled records).';if(/hypertension/i.test(low))return 'Protected result: approximately '+Math.round(total*0.154).toLocaleString()+' hypertension cases across the selected protected scope. No patient-level rows are released.';if(/average age|age range/i.test(low))return 'Protected result: the modeled population is concentrated in the 40–60 age range, with an estimated protected average of '+(41+(Math.abs(seed)%17))+' years.';if(/respiratory/i.test(low))return 'Protected result: respiratory illness represents approximately '+(7+(Math.abs(seed)%55)/10).toFixed(1)+'% of the protected population, reported only as an aggregate.';if(/how many records/i.test(low))return 'Protected result: connected establishments collectively hold '+total.toLocaleString()+' records; raw records remain inside each custodian.';if(/percentage.*40.?60|generalized/i.test(low))return 'Generalized protected result: about '+(28+(Math.abs(seed)%31))+'% of the connected population falls within the requested age band.';return 'Protected aggregate answer: '+count.toLocaleString()+' modeled records match the requested population scope. Raw rows remain local.'}
 function classify(x){let lower=x.toLowerCase(),individual=/(?:\bmrn\b|\bssn\b|\bemirates id\b|\bdate of birth\b|\bdob\b|\bnamed patient\b|\bspecific patient\b|\bspecific person\b|\bone person\b|\bidentify (?:the )?(?:patient|person)\b|\bexact record\b|\bpatient\s+[a-z]{2,}(?:\s+[a-z]{2,})*\s+(?:diagnosis|record|date of birth|admitted)\b)/i.test(lower),blocked=individual&&state().policy.individual===false;return{decision:blocked?'BLOCKED':'ALLOWED',risk:blocked?'HIGH':(/rare|small|exact|single/i.test(lower)?'MEDIUM':'LOW'),individual,reason:blocked?'Blocked because the request could reveal information about an identifiable person.':'Approved because the request asks for an aggregate or generalized result rather than an individual record.'}}
 async function backendAnswer(x){try{let r=await fetch('/api/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:x,epsilon:+state().eps||.6,session_id:'WEB-DEMO'})});if(!r.ok)return null;return await r.json()}catch(e){return null}}
 window.ex=function(kind){let arr=kind==='blocked'?risky:safe;let pick=arr[Math.floor(Math.random()*arr.length)];q.value=pick;send()};window.send=async function(){let x=q.value.trim();if(!x)return;let c=classify(x),answer=c.decision==='BLOCKED'?'No answer is released because this request is blocked. Try an aggregate or generalized version.':answerFor(x);let remote=null;if(c.decision==='ALLOWED')remote=await backendAnswer(x);if(remote&&remote.action==='ALLOW'&&remote.response)answer=remote.response;let qs=queries();qs.push({q:x,decision:c.decision,risk:c.risk,reason:c.reason,answer,actor:'analyst-07',ts:Date.now()});setQueries(qs.slice(-200));let chat=document.getElementById('chat');chat.innerHTML+='<div class="bubble user">'+esc(x)+'</div><div class="bubble bot"><b class="'+(c.decision==='BLOCKED'?'red':'green')+'">'+(c.decision==='BLOCKED'?'✕ BLOCKED':'✓ APPROVED')+'</b><br>'+c.reason+'<br><span class="muted">'+esc(answer)+'</span></div>';let pipe=document.getElementById('pipe');if(pipe)pipe.innerHTML='<div class="decision-steps"><span>REQUEST ✓</span><span>IDENTIFIER '+(c.individual?'⚠':'✓')+'</span><span>RISK '+c.risk+' ✓</span><span>POLICY '+(c.decision==='BLOCKED'?'✕':'✓')+'</span><span>BUDGET '+(c.decision==='BLOCKED'?'HELD':'✓')+'</span><strong>'+c.decision+'</strong></div><div class="guide-callout" style="margin-top:12px"><b>Recommendation</b><span>'+(c.decision==='BLOCKED'?'Ask for a generalized aggregate, prevalence, range, or establishment-level statistic instead.':'Prefer aggregate counts, prevalence, ranges, or protected model updates; avoid identifiers and rare single-person slices.')+'</span></div><div class="guide-callout"><b>Protected answer</b><span>'+esc(answer)+'</span></div>';log('Analytics request',x,c.decision==='BLOCKED'?'HIGH':'INFO');if(c.decision==='BLOCKED'&&qs.slice(-4).filter(z=>z.decision==='BLOCKED').length>=3)log('Query burst','Repeated high-risk requests detected','HIGH');q.value='';updateGlobal()};const panel=q.closest('.card');if(panel&&!document.getElementById('rec-request')){let r=document.createElement('div');r.id='rec-request';r.className='guide-callout';r.innerHTML='<b>Recommended request</b><span>Try a generalized aggregate such as “What is the prevalence of diabetes across connected establishments?”</span>';panel.insertBefore(r,q.closest('.row').nextElementSibling)}}

function decisions(){if(file()!=='decisions.html')return;let main=document.querySelector('main'),table=document.getElementById('rows');if(!main||!table)return;let q=queries();let a=document.getElementById('a'),b=document.getElementById('b');if(a)a.textContent=q.filter(x=>x.decision==='ALLOWED').length;if(b)b.textContent=q.filter(x=>x.decision==='BLOCKED').length;let gen=document.querySelector('.g3 .card:nth-child(2) .num');if(gen)gen.textContent=q.filter(x=>x.risk==='MEDIUM').length;table.innerHTML=q.slice().reverse().map(x=>'<tr><td>'+new Date(x.ts).toLocaleTimeString()+'</td><td>'+esc(x.q)+'</td><td class="'+(x.decision==='BLOCKED'?'red':'green')+'">'+x.decision+'</td><td>'+esc(x.risk||'LOW')+'</td><td>'+esc(x.reason||'Policy evaluation completed.')+'</td></tr>').join('')||'<tr><td colspan="5">No decisions yet.</td></tr>';let th=table.closest('table')?.querySelector('thead tr');if(th&&th.children.length===3)th.innerHTML+='<th>RISK</th><th>WHY</th>';}

function attack(){if(file()!=='attacklab.html')return;let main=document.querySelector('main');if(!main||document.getElementById('attack-live'))return;let old=main.querySelector('.row');if(old)old.remove();let c=document.createElement('div');c.id='attack-live';c.className='card';c.innerHTML='<div class="section-head"><div><h3>Interactive attack configuration</h3><p class="muted">Use the AEGIS-inspired attack scenarios, change the observations, and compare a naive release with privacy protection.</p></div><span id="at-verdict" class="tag">READY</span></div><div class="grid g4"><div><label class="muted">Scenario</label><select id="at-scenario" class="input"><option>Membership inference</option><option>Differencing attack</option><option>Rare subgroup reconstruction</option><option>Repeated query attack</option><option>Gradient inversion</option><option>Model poisoning</option></select></div><div><label class="muted">Target population size</label><input id="at-size" class="input" type="number" min="2" value="20"></div><div><label class="muted">Observed query count</label><input id="at-obs" class="input" type="number" min="1" value="6"></div><div><label class="muted">Attack observation (%)</label><input id="at-signal" class="input" type="number" min="0" max="100" value="50"></div></div><div class="row" style="margin-top:14px"><button class="btn" id="at-naive">▶ Run naive attack</button><button class="btn primary" id="at-protected">▶ Run protected attack</button><button class="btn" id="at-random">↻ Random scenario</button><button class="btn" id="at-reset">Reset inputs</button></div><div class="grid g2" style="margin-top:15px"><div class="card"><h3>Naive confidence</h3><div id="n" class="num red">—</div><p id="n-note" class="muted">Exact/raw observation baseline.</p></div><div class="card"><h3>Protected confidence</h3><div id="p" class="num green">—</div><p id="p-note" class="muted">DP / protection-aware estimate.</p></div></div><div class="card" style="margin-top:15px"><div class="section-head"><div><h3>Attack observation field</h3><p class="muted">The population dots are regenerated from the current target size, observation count, signal and privacy setting.</p></div><span id="at-obstext" class="muted"></span></div><div id="chart" class="chart" style="height:240px"></div></div><div id="at-method" class="guide-callout" style="margin-top:15px"><b>Attack interpretation</b><span>Change any input to see the modeled confidence move. This is an interactive demonstration; measured research results are shown on the Dashboard and in the bundled research report.</span></div><div id="at-measured" class="guide-callout"><b>Measured research anchor</b><span>Select Membership inference, Gradient inversion, or Model poisoning and run an attack to load the bundled executed benchmark when API mode is available. Offline mode retains the measured values in the package.</span></div>';main.appendChild(c);
 function metrics(){let size=Math.max(2,+document.getElementById('at-size').value||20),obs=Math.max(1,+document.getElementById('at-obs').value||6),signal=Math.max(0,Math.min(100,+document.getElementById('at-signal').value||0)),scenario=document.getElementById('at-scenario').value,boost={'Membership inference':6,'Differencing attack':12,'Rare subgroup reconstruction':16,'Repeated query attack':10,'Gradient inversion':20,'Model poisoning':24}[scenario]||8,eps=Math.max(.05,+state().eps||.6),exposure=(obs/(obs+4))*(signal/100),sizeFactor=Math.min(1.4,30/size),naive=Math.round(Math.min(99,12+exposure*58+boost+sizeFactor*8)),protection=(scenario==='Model poisoning'?0.48:0.22+0.06*Math.min(2,eps)),protected=Math.round(Math.max(1,Math.min(95,naive*protection-(signal*.08)+Math.min(8,eps*1.2))));return{size,obs,signal,scenario,eps,naive,protected}}
 function draw(mode,runIt){let m=metrics();document.getElementById('n').textContent=m.naive+'%';document.getElementById('p').textContent=m.protected+'%';document.getElementById('at-obstext').textContent=m.obs+' observations · signal '+m.signal+'% · target '+m.size+' · ε '+m.eps.toFixed(2);let chart=document.getElementById('chart');chart.innerHTML='';let count=Math.min(120,Math.max(12,m.obs*4+Math.round(m.signal/4)));let protectedMode=mode==='protected';for(let i=0;i<count;i++){let d=document.createElement('i');d.className='dot';let spread=protectedMode?(18+m.eps*7):(4+Math.max(0,35-m.signal*.25));let seed=(i*47+m.size*13+m.obs*17+Math.round(m.signal*3))%100;d.style.left=(3+seed*.94)+'%';d.style.top=(7+((i*29+Math.round(spread*3))%84))+'%';d.style.opacity=protectedMode?(0.10+(i%5)*.055):(0.38+(i%5)*.09);d.style.transform='scale('+(protectedMode?(0.45+m.eps*.08):(0.65+m.signal*.008))+')';chart.appendChild(d)}let gap=m.naive-m.protected;document.getElementById('at-verdict').textContent=runIt?(protectedMode?'ATTACK DEGRADED':'LEAKAGE SIGNAL'):'LIVE ESTIMATE';document.getElementById('at-method').innerHTML='<b>Attack interpretation</b><span>'+esc(m.scenario)+': naive confidence <b>'+m.naive+'%</b>, protected confidence <b>'+m.protected+'%</b>, reduction '+Math.max(0,gap)+' percentage points. '+(protectedMode?'The protected path adds uncertainty and reduces distinguishability.':'The naive path exposes a stronger signal because no privacy protection is applied.')+'</span>';if(runIt){log('Attack simulation',m.scenario+' · '+mode+' · naive '+m.naive+'% · protected '+m.protected+'%',''+(protectedMode?'INFO':'HIGH'));loadMeasured(m)}}
 async function loadMeasured(m){let box=document.getElementById('at-measured');if(!box)return;try{let r=await fetch('/api/attack',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scenario:m.scenario,population:m.size,observations:m.obs,signal:m.signal,epsilon:m.eps})});if(!r.ok)return;let d=await r.json();if(d.measured){box.innerHTML='<b>Measured research anchor</b><span>'+esc(d.measured.note||'Bundled executed benchmark.')+' '+esc(JSON.stringify(d.measured))+'</span>'}}catch(e){/* offline dashboard intentionally falls back to local model */}}
 ['at-size','at-obs','at-signal','at-scenario'].forEach(id=>document.getElementById(id).addEventListener('input',()=>draw('protected',false)));document.getElementById('at-naive').onclick=()=>draw('naive',true);document.getElementById('at-protected').onclick=()=>draw('protected',true);document.getElementById('at-random').onclick=()=>{let opts=['Membership inference','Differencing attack','Rare subgroup reconstruction','Repeated query attack','Gradient inversion','Model poisoning'];document.getElementById('at-scenario').value=opts[Math.floor(Math.random()*opts.length)];document.getElementById('at-size').value=5+Math.floor(Math.random()*80);document.getElementById('at-obs').value=2+Math.floor(Math.random()*18);document.getElementById('at-signal').value=5+Math.floor(Math.random()*95);draw('protected',false)};document.getElementById('at-reset').onclick=()=>{document.getElementById('at-scenario').selectedIndex=0;document.getElementById('at-size').value=20;document.getElementById('at-obs').value=6;document.getElementById('at-signal').value=50;draw('protected',false)};draw('protected',false);window.run=function(k){draw(k==='n'?'naive':'protected',true)}}

function ledger(){if(file()!=='ledger.html')return;let main=document.querySelector('main');if(!main||document.getElementById('ledger-live'))return;main.querySelectorAll('.grid.g3').forEach(x=>x.remove());let c=document.createElement('div');c.id='ledger-live';c.className='card';c.innerHTML='<div class="section-head"><div><h3>Privacy allowance by custodian</h3><p class="muted">The technical unit is epsilon (ε). Think of it as a privacy allowance consumed by protected releases.</p></div><button id="led-new" class="btn primary">↻ Start new epoch</button></div><div id="led-list" class="grid g2"></div><div class="card" style="margin-top:15px"><h3>Training epochs by establishment</h3><div id="epoch-chart" class="epoch-chart"></div></div>';main.appendChild(c);function render(){let s=state();document.getElementById('led-list').innerHTML=s.custodians.map((x,i)=>'<div class="card"><div class="section-head"><div><h3>'+esc(x.name)+'</h3><span class="muted">'+x.records.toLocaleString()+' records · '+(x.connected?'connected':'offline')+'</span></div><span class="tag '+(x.connected?'green':'amber')+'">'+(x.connected?'CONNECTED':'OFFLINE')+'</span></div><div class="grid g3"><div><span class="muted">Remaining allowance</span><div class="num">'+x.budget.toFixed(2)+' ε</div></div><div><span class="muted">Epochs</span><input class="input led-epoch" data-i="'+i+'" type="number" min="1" max="20" value="'+x.epochs+'"></div><div><span class="muted">Action</span><button class="btn led-spend" data-i="'+i+'">Run protected query</button></div></div><div class="bar"><i style="width:'+Math.max(0,Math.min(100,(1-x.budget/5)*100))+'%"></i></div></div>').join('');document.querySelectorAll('.led-epoch').forEach(inp=>inp.onchange=()=>{let ss=state(),i=+inp.dataset.i;ss.custodians[i].epochs=Math.max(1,Math.min(20,+inp.value||1));ss.epoch=ss.custodians[i].epochs;save(ss);log('Epoch updated',ss.custodians[i].name+' · '+ss.custodians[i].epochs+' epochs','INFO');render()});document.querySelectorAll('.led-spend').forEach(btn=>btn.onclick=()=>{let ss=state(),i=+btn.dataset.i;ss.custodians[i].budget=Math.max(0,ss.custodians[i].budget-.2);save(ss);log('Privacy allowance consumed',ss.custodians[i].name+' · 0.20 ε','INFO');render()});let ec=document.getElementById('epoch-chart');ec.innerHTML=s.custodians.map(x=>'<div class="epoch-row"><b>'+esc(x.name)+'</b><div class="epoch-track"><i style="width:'+Math.min(100,x.epochs/20*100)+'%"></i><span>Epoch '+x.epochs+'</span></div></div>').join('')}render();document.getElementById('led-new').onclick=()=>{let ss=state();ss.epoch++;if(ss.epoch>20)ss.epoch=1;ss.custodians.forEach(x=>{x.epochs=ss.epoch;x.budget=5});save(ss);log('New training epoch','Epoch '+ss.epoch+' started; privacy allowances reset for the new round','INFO');render()};window.resetB=()=>document.getElementById('led-new').click()}

function tradeoff(){if(file()!=='tradeoff.html')return;let main=document.querySelector('main');if(!main||document.getElementById('trade-live'))return;let old=main.querySelector('.card');if(old)old.remove();let c=document.createElement('div');c.id='trade-live';c.className='card';c.innerHTML='<div class="section-head"><div><h3>Privacy protection vs answer accuracy</h3><p class="muted">Lower ε means stronger protection and more uncertainty. Higher ε means more precise answers with greater privacy exposure.</p></div><span id="tr-val" class="tag">ε = 0.60</span></div><input id="tr-eps" type="range" min="0.05" max="5" step="0.05" value="0.6" style="width:100%"><div class="grid g4" style="margin-top:16px"><div><span class="muted">Privacy protection</span><div id="tr-prot" class="num green">STRONG</div></div><div><span class="muted">Answer precision</span><div id="tr-acc" class="num">82%</div></div><div><span class="muted">Noise level</span><div id="tr-noise" class="num amber">MODERATE</div></div><div><span class="muted">Attack confidence</span><div id="tr-attack" class="num red">18%</div></div></div><div class="card" style="margin-top:18px"><div class="section-head"><div><h3>Interactive privacy setting</h3><p class="muted">Move the dotted population to see how stronger protection spreads observations and reduces distinguishability.</p></div><span id="tr-dots-label" class="muted"></span></div><div id="tr-dots" class="chart" style="height:180px"></div></div><div class="chart" id="tr-chart" style="height:250px;margin-top:18px"></div><div id="tr-help" class="guide-callout"><b>Plain-language reading</b><span>Move the slider left for stronger privacy or right for a more precise answer.</span></div>';main.appendChild(c);function draw(){let e=+document.getElementById('tr-eps').value,t=Math.min(1,e/2.5),acc=Math.round(64+31*t),attack=Math.round(5+58*t),prot=e<.3?'MAXIMUM':e<.8?'STRONG':e<1.6?'BALANCED':'LIGHT',noise=e<.3?'HIGH':e<.8?'MODERATE':e<1.6?'LOW':'VERY LOW';document.getElementById('tr-val').textContent='ε = '+e.toFixed(2);document.getElementById('tr-prot').textContent=prot;document.getElementById('tr-acc').textContent=acc+'%';document.getElementById('tr-noise').textContent=noise;document.getElementById('tr-attack').textContent=attack+'%';let ch=document.getElementById('tr-chart');ch.innerHTML='<svg viewBox="0 0 1000 250" preserveAspectRatio="none" style="width:100%;height:100%"><path d="M30 215 C 220 200, 360 160, 500 125 S 770 65, 970 25" fill="none" stroke="currentColor" stroke-width="4" opacity=".85"/><line x1="30" y1="215" x2="970" y2="215" stroke="currentColor" opacity=".15"/><circle cx="'+(30+940*t)+'" cy="'+(215-190*t)+'" r="8" fill="currentColor"/><text x="30" y="240" font-size="14" fill="currentColor" opacity=".65">Stronger privacy</text><text x="805" y="240" font-size="14" fill="currentColor" opacity=".65">More precise answer</text></svg>';let d=document.getElementById('tr-dots');d.innerHTML='';let spread=2+Math.round((1-t)*10);let count=36;for(let i=0;i<count;i++){let dot=document.createElement('i');dot.className='dot';dot.style.left=(8+Math.random()*84)+'%';dot.style.top=(10+Math.random()*78)+'%';dot.style.opacity=(.18+t*.65);dot.style.transform='scale('+(0.6+Math.random()*(0.5+spread/12))+')';d.appendChild(dot)}document.getElementById('tr-dots-label').textContent='ε '+e.toFixed(2)+' · protection '+prot.toLowerCase()+' · noise '+noise.toLowerCase();document.getElementById('tr-help').innerHTML='<b>Current setting</b><span>At ε '+e.toFixed(2)+', the answer is about '+acc+'% precise while modeled attack confidence is '+attack+'%. The dotted field visualizes the uncertainty introduced by privacy protection.</span>';let s=state();s.eps=e;save(s)}document.getElementById('tr-eps').oninput=draw;draw()}

function hospitals(){if(file()!=='hospitals.html')return;let main=document.querySelector('main');if(!main||document.getElementById('infra-live'))return;main.querySelectorAll('.grid.g3').forEach(x=>x.remove());let c=document.createElement('div');c.id='infra-live';c.className='card';c.innerHTML='<div class="section-head"><div><h3>Infrastructure registry</h3><p class="muted">Add an establishment, provide its record count, attach a dataset template and choose whether it is connected.</p></div><span class="tag green"><b data-custodian-count>4</b> connected</span></div><div class="grid g3"><input id="hs-name" class="input" placeholder="Infrastructure name, e.g. Hospital E"><input id="hs-records" class="input" type="number" min="0" placeholder="Number of records"><select id="hs-connected" class="input"><option value="yes">Connect immediately</option><option value="no">Keep offline</option></select></div><div class="row" style="margin-top:12px"><input id="hs-file" type="file" accept=".xlsx,.xls,.csv" class="input"><button id="hs-add" class="btn primary">Add infrastructure</button><a id="download-template" class="btn" download="ppa-gov-custodian-dataset.xlsx">Download Excel dataset template</a></div><div id="hs-msg" class="muted" style="margin-top:10px"></div><div class="space"></div><h3>Data release policy</h3><p class="muted">The administrator decides what categories the control plane may release. The Analyst Console uses these settings.</p><div class="row policy-editor"><label><input type="checkbox" data-pol="aggregate" checked> Aggregate statistics</label><label><input type="checkbox" data-pol="model" checked> Protected model updates</label><label><input type="checkbox" data-pol="demographic" checked> Demographic ranges</label><label><input type="checkbox" data-pol="individual"> Individual records</label></div><button id="hs-savepol" class="btn">Save release policy</button><div class="space"></div><div id="hs-list"></div>';main.appendChild(c);function render(){let s=state();document.querySelectorAll('[data-custodian-count]').forEach(e=>e.textContent=s.custodians.filter(x=>x.connected).length);document.getElementById('hs-list').innerHTML='<div class="grid g3">'+s.custodians.map(x=>'<div class="card"><div class="section-head"><div><h3>'+esc(x.name)+'</h3><p class="muted">'+x.records.toLocaleString()+' records</p></div><span class="tag '+(x.connected?'green':'amber')+'">● '+(x.connected?'CONNECTED':'OFFLINE')+'</span></div><p class="muted">Local privacy engine · raw rows remain local.</p></div>').join('')+'</div>';document.querySelectorAll('[data-pol]').forEach(i=>i.checked=!!s.policy[i.dataset.pol])}render();document.getElementById('hs-add').onclick=()=>{let s=state(),name=document.getElementById('hs-name').value.trim(),records=Math.max(0,+document.getElementById('hs-records').value||0),connected=document.getElementById('hs-connected').value==='yes',upload=document.getElementById('hs-file').files[0];if(!name){document.getElementById('hs-msg').textContent='Enter an infrastructure name.';return}if(s.custodians.some(x=>x.name.toLowerCase()===name.toLowerCase())){document.getElementById('hs-msg').innerHTML='<b class="amber">Already available:</b> '+esc(name)+' is already registered.';return}if(!records){document.getElementById('hs-msg').textContent='Enter the number of records for this establishment.';return}s.custodians.push({name,records,connected,epochs:s.epoch,budget:5,dataset:upload?upload.name:null});save(s);log('Infrastructure added',name+' · '+records.toLocaleString()+' records · '+(connected?'connected':'offline'),'INFO');document.getElementById('hs-msg').innerHTML='<b class="green">Added:</b> '+esc(name)+' is '+(connected?'connected and ready.':'registered offline; connect it later from this page.')+(upload?' Dataset attached: '+esc(upload.name):'');document.getElementById('hs-name').value='';document.getElementById('hs-records').value='';document.getElementById('hs-file').value='';render();updateGlobal()};document.getElementById('hs-savepol').onclick=()=>{let s=state();document.querySelectorAll('[data-pol]').forEach(i=>s.policy[i.dataset.pol]=i.checked);save(s);log('Release policy updated','Administrator changed permitted data categories','INFO');document.getElementById('hs-msg').textContent='Release policy saved. New Analyst Console decisions will use these rules.'};
 // Create a real xlsx download without external libraries using a minimal SpreadsheetML workbook with .xlsx-compatible Excel opening fallback? Use .xls MIME for reliability, but name template as .xls.
 let xml='<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="CustodianData"><Table><Row><Cell><Data ss:Type="String">record_id</Data></Cell><Cell><Data ss:Type="String">age</Data></Cell><Cell><Data ss:Type="String">condition</Data></Cell><Cell><Data ss:Type="String">region</Data></Cell></Row><Row><Cell><Data ss:Type="String">R-001</Data></Cell><Cell><Data ss:Type="Number">52</Data></Cell><Cell><Data ss:Type="String">Diabetes</Data></Cell><Cell><Data ss:Type="String">Dubai</Data></Cell></Row></Table></Worksheet></Workbook>';let blob=new Blob([xml],{type:'application/vnd.ms-excel'});let a=document.getElementById('download-template');a.href=URL.createObjectURL(blob);a.download='ppa-gov-custodian-dataset.xls';a.textContent='Download Excel dataset template (.xls)'}

function threatEnh(){if(file()!=='threat.html')return;let main=document.querySelector('main');if(!main)return;let box=document.getElementById('log');if(!box)return;let stream=box.closest('.card');if(stream){stream.innerHTML='<div class="section-head"><div><h3>Live security event stream</h3><p class="muted">Security telemetry is generated from this session and from threat-specific detection activity.</p></div><button id="th-refresh" class="btn">↻ Generate event</button></div><div id="th-stream" class="event-stream"></div>'}function render(){let s=state(),base=s.events.slice(0,30),special=JSON.parse(localStorage.getItem('ppa-threat-events')||'[]'),all=[...special,...base].sort((a,b)=>b.ts-a.ts).slice(0,30),el=document.getElementById('th-stream');if(el)el.innerHTML=all.map((e,i)=>'<div class="event-row"><span class="tag '+(e.severity==='HIGH'?'red':e.severity==='MEDIUM'?'amber':'green')+'">'+esc(e.severity)+'</span><b>'+esc(e.type)+'</b><span class="muted">'+esc(e.detail)+'</span><time>'+new Date(e.ts).toLocaleTimeString()+'</time></div>').join('')||'<p class="muted">No security events yet.</p>';let blocked=queries().filter(x=>x.decision==='BLOCKED').length,high=queries().filter(x=>x.risk==='HIGH').length;document.getElementById('ev').textContent=blocked+high;document.getElementById('lvl').textContent=(blocked+high)>=5?'CRITICAL':(blocked+high)>=2?'ELEVATED':'LOW';let df=JSON.parse(localStorage.getItem('ppa-diff')||'0');document.getElementById('df').textContent=df}function add(){let types=[['Threat sensor','Repeated high-risk query pattern','HIGH'],['Inference monitor','Membership-inference signal observed','HIGH'],['Budget guard','Privacy allowance approaching review threshold','MEDIUM'],['Traffic monitor','Unusual query frequency detected','MEDIUM'],['Differencing monitor','Related filter sequence requires analysis','HIGH'],['Policy engine','Protected aggregate request evaluated','INFO']];let x=types[Math.floor(Math.random()*types.length)],arr=JSON.parse(localStorage.getItem('ppa-threat-events')||'[]');arr.unshift({ts:Date.now(),type:x[0],detail:x[1],severity:x[2]});localStorage.setItem('ppa-threat-events',JSON.stringify(arr.slice(0,80)));log(x[0],x[1],x[2]);render()}document.getElementById('th-refresh').onclick=add;render();if(!window.__thTimer)window.__thTimer=setInterval(()=>{if(file()==='threat.html')add()},7000)}
function differencing(){if(file()!=='differencing.html')return;let main=document.querySelector('main');if(!main||document.getElementById('diff-live'))return;let old=main.querySelector('.card');if(old)old.remove();let c=document.createElement('div');c.id='diff-live';c.className='card';c.innerHTML='<div class="section-head"><div><h3>Interactive differencing detector</h3><p class="muted">Build a sequence of related queries, then analyze whether the differences narrow the population too far.</p></div><span id="df-status" class="tag">READY</span></div><div class="grid g3"><div><label class="muted">Action</label><select id="df-action" class="input"><option value="build">Build query sequence</option><option value="analyze">Analyze sequence</option></select></div><div><label class="muted">Starting population</label><input id="df-pop" class="input" type="number" min="2" value="500"></div><div><label class="muted">Narrowing steps</label><input id="df-steps" class="input" type="number" min="2" max="6" value="3"></div></div><div class="grid g3" style="margin-top:12px"><input id="df-q1" class="input" value="Region = Dubai"><input id="df-q2" class="input" value="Condition = Diabetes"><input id="df-q3" class="input" value="Age = 40–45"></div><div class="row" style="margin-top:12px"><button id="df-build" class="btn">＋ Build sequence</button><button id="df-analyze" class="btn primary">▶ Analyze sequence</button><button id="df-random" class="btn">↻ Randomize</button></div><div id="df-seq" class="card" style="margin-top:14px"><h3>Query sequence</h3><p class="muted">Add or edit filters, then analyze them.</p></div><div id="df-result" class="card" style="margin-top:14px">No analysis yet.</div>';main.appendChild(c);function vals(){return[document.getElementById('df-q1').value.trim(),document.getElementById('df-q2').value.trim(),document.getElementById('df-q3').value.trim()].filter(Boolean)}function build(){let v=vals(),pop=Math.max(2,+document.getElementById('df-pop').value||500);document.getElementById('df-seq').innerHTML='<h3>Query sequence</h3>'+v.map((x,i)=>'<div class="event-row"><span class="tag">Q'+(i+1)+'</span><b>'+esc(x)+'</b><span class="muted">estimated remaining population: '+Math.max(1,Math.round(pop*Math.pow(.42,i+1))).toLocaleString()+'</span></div>').join('');document.getElementById('df-status').textContent='SEQUENCE BUILT';return v}function analyze(){let v=build(),pop=Math.max(2,+document.getElementById('df-pop').value||500),final=Math.max(1,Math.round(pop*Math.pow(.42,v.length))),risk=final<=5?'HIGH':final<=20?'MEDIUM':'LOW',detected=risk==='HIGH';document.getElementById('df-result').innerHTML='<b class="'+(detected?'red':'green')+'">'+(detected?'⚠ DIFFERENCING RISK DETECTED':'✓ NO HIGH-RISK DIFFERENCING SIGNAL')+'</b><p>After '+v.length+' narrowing steps, the modeled remaining population is <b>'+final+'</b>.</p><p class="muted">'+(detected?'The sequence is too selective; block or generalize the final release and create an audit event.':'The sequence remains sufficiently broad for this simulated check.')+'</p>';document.getElementById('df-status').textContent=detected?'BLOCK REVIEW':'ANALYZED';if(detected){localStorage.setItem('ppa-diff',String((+localStorage.getItem('ppa-diff')||0)+1));log('Differencing detection',v.join(' → '),'HIGH')}else log('Differencing analysis',v.join(' → '),'INFO')}document.getElementById('df-build').onclick=build;document.getElementById('df-analyze').onclick=analyze;document.getElementById('df-action').onchange=e=>{if(e.target.value==='build')build();else analyze()};document.getElementById('df-random').onclick=()=>{let sets=[['Region = Abu Dhabi','Condition = Hypertension','Age = 70+'],['Region = Dubai','Condition = Asthma','Age = 18–25'],['Region = Sharjah','Condition = Rare respiratory condition','Age = 50–55'],['Region = Ajman','Condition = Diabetes','Establishment = single site']][Math.floor(Math.random()*4)];['df-q1','df-q2','df-q3'].forEach((id,i)=>document.getElementById(id).value=sets[i]);build()};build()}

function monitorEnh(){if(file()!=='monitor.html')return;let main=document.querySelector('main'),table=document.querySelector('#rows');if(!main||!table||document.getElementById('qm-filter'))return;let c=document.createElement('div');c.id='qm-filter';c.className='card';c.style.margin='15px 0';c.innerHTML='<div class="section-head"><div><h3>Query activity monitor</h3><p class="muted">Risk telemetry is separate from the access decision record.</p></div><select id="qm-select" class="input"><option>All activity</option><option>Safe</option><option>Medium risk</option><option>High risk</option><option>Blocked</option></select></div><div class="grid g4" style="margin-top:12px"><div><span class="muted">Total</span><div id="qm-total" class="num">0</div></div><div><span class="muted">Safe</span><div id="qm-safe" class="num green">0</div></div><div><span class="muted">High risk</span><div id="qm-high" class="num red">0</div></div><div><span class="muted">Blocked</span><div id="qm-block" class="num amber">0</div></div></div>';main.insertBefore(c,table.closest('.card'));function render(){let all=queries(),f=document.getElementById('qm-select').value,q=all;if(f==='Safe')q=all.filter(x=>x.decision==='ALLOWED'&&x.risk==='LOW');if(f==='Medium risk')q=all.filter(x=>x.risk==='MEDIUM');if(f==='High risk')q=all.filter(x=>x.risk==='HIGH');if(f==='Blocked')q=all.filter(x=>x.decision==='BLOCKED');['total','safe','high','block'].forEach((id)=>{let el=document.getElementById('qm-'+id);if(el)el.textContent=id==='total'?all.length:id==='safe'?all.filter(x=>x.risk==='LOW').length:id==='high'?all.filter(x=>x.risk==='HIGH').length:all.filter(x=>x.decision==='BLOCKED').length});table.innerHTML=q.slice().reverse().map(x=>'<tr><td>'+new Date(x.ts).toLocaleTimeString()+'</td><td>'+esc(x.actor||'analyst-07')+'</td><td class="'+(x.decision==='BLOCKED'?'red':'green')+'">'+x.decision+'</td><td>'+esc(x.q)+'</td><td>'+esc(x.risk||'LOW')+'</td></tr>').join('')||'<tr><td colspan="5">No matching activity.</td></tr>'}document.getElementById('qm-select').onchange=render;let th=table.closest('table')?.querySelector('thead tr');if(th&&th.children.length===4)th.innerHTML+='<th>RISK</th>';render()}

function auditEnh(){if(file()!=='audit.html')return;let main=document.querySelector('main'),box=document.getElementById('audit');if(!main||!box)return;window.clearLog=function(){setQueries([]);let s=state();s.events=[];save(s);location.reload()};let s=state(),q=queries();box.innerHTML=[...s.events.map(e=>({ts:e.ts,type:e.type,severity:e.severity,detail:e.detail})),...q.map(x=>({ts:x.ts,type:'Analytics request',severity:x.decision==='BLOCKED'?'HIGH':'INFO',detail:x.q+' · '+(x.reason||'Decision evaluated')}))].sort((a,b)=>b.ts-a.ts).slice(0,120).map((e,i)=>'<div class="event-row"><span class="tag '+(e.severity==='HIGH'?'red':'green')+'">EVT-'+(1000+i)+'</span><b>'+esc(e.type)+'</b><span class="muted">'+esc(e.detail)+'</span><time>'+new Date(e.ts).toLocaleString()+'</time></div>').join('')||'<p class="muted">No audit events yet.</p>'}
function exports(){if(!['monitor.html','audit.html'].includes(file()))return;let main=document.querySelector('main');if(document.getElementById('export-btn'))return;let btn=document.createElement('button');btn.id='export-btn';btn.className='btn primary';btn.textContent='Export Excel';btn.onclick=()=>{let rows=file()==='monitor.html'?queries().map(x=>[new Date(x.ts).toLocaleString(),x.actor||'analyst-07',x.decision,x.risk||'LOW',x.q,x.reason||'']):state().events.map(x=>[new Date(x.ts).toLocaleString(),'PPA-GOV',x.type,x.severity,x.detail]);let head=file()==='monitor.html'?['Timestamp','Actor','Decision','Risk','Request','Reason']:['Timestamp','Actor','Event','Severity','Details'];let xml='<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="PPA-GOV"><Table><Row>'+head.map(h=>'<Cell><Data ss:Type="String">'+esc(h)+'</Data></Cell>').join('')+'</Row>'+rows.map(r=>'<Row>'+r.map(v=>'<Cell><Data ss:Type="String">'+esc(v)+'</Data></Cell>').join('')+'</Row>').join('')+'</Table></Worksheet></Workbook>';let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([xml],{type:'application/vnd.ms-excel'}));a.download=file()==='monitor.html'?'ppa-gov-query-log.xls':'ppa-gov-audit-trail.xls';a.click();log('Export generated',a.download,'INFO')};let h=main.querySelector('.eyebrow');if(h)h.parentNode.insertBefore(btn,h.nextSibling)}
function health(){if(file()!=='health.html')return;let main=document.querySelector('main');if(!main||document.getElementById('health-note'))return;let c=document.createElement('div');c.id='health-note';c.className='card';c.style.marginTop='15px';c.innerHTML='<h3>Recommended operational action</h3><p id="health-msg" class="muted"></p>';main.appendChild(c);let q=queries(),blocked=q.filter(x=>x.decision==='BLOCKED').length,high=q.filter(x=>x.risk==='HIGH').length;c.querySelector('#health-msg').textContent=blocked>=3||high>=3?'Controls need attention: review recent high-risk requests, inspect Threat Detection, and verify privacy-budget pressure before allowing further sensitive analytics.':'System is healthy: maintain routine monitoring, validate policy changes periodically, and keep the demonstration state reproducible.'}
function overviewEnh(){if(file()!=='overview.html')return;let box=document.getElementById('overview-live-stats');if(!box)return;let s=state(),q=queries(),connected=s.custodians.filter(c=>c.connected),blocked=q.filter(x=>x.decision==='BLOCKED').length,high=q.filter(x=>x.risk==='HIGH'||x.risk==='CRITICAL').length;let threat=(blocked+high)>=5?'CRITICAL':(blocked+high)>=2?'ELEVATED':'LOW';let raw=0;box.innerHTML='<div class="card"><h3>'+connected.length+'</h3><p class="muted">Connected custodians</p><div class="num">'+connected.length+'</div><span class="tag green">LIVE STATE</span></div><div class="card"><h3>0</h3><p class="muted">Raw records shared</p><div class="num green">0</div><span class="tag green">LOCAL ONLY</span></div><div class="card"><h3>ACTIVE</h3><p class="muted">Privacy engine</p><div class="num">ACTIVE</div><span class="tag">ε '+(+s.eps||.6).toFixed(2)+'</span></div><div class="card"><h3>'+threat+'</h3><p class="muted">Threat level</p><div class="num '+(threat==='LOW'?'green':'amber')+'">'+threat+'</div><span class="tag">'+q.length+' requests · '+s.events.length+' events</span></div>'}

function policyEnh(){if(file()!=='policy.html')return;let box=document.getElementById('policy-live'),summary=document.getElementById('policy-summary');if(!box||!summary)return;let s=state(),p=s.policy;let cards=[['aggregate','✓ Population-level analytics','Counts and rates, prevalence, aggregated statistics, population trends'],['model','✓ Protected model updates','Federated model updates protected before aggregation'],['demographic','✓ Demographic ranges','Generalized age, region and other demographic ranges'],['individual','✕ Individual-level access','Patient records, diagnoses, names, identifiers and exact lookups']];box.innerHTML=cards.map(x=>{let on=!!p[x[0]];return '<div class="card"><h3>'+x[1]+'</h3><p class="muted">'+(on?'Allowed by current release policy':'Disabled by current release policy')+'</p><p>'+x[2]+'</p><b class="'+(on?'green':'red')+'">'+(on?'RELEASABLE':'BLOCKED')+'</b></div>'}).join('');let allowed=[];if(p.aggregate)allowed.push('aggregate statistics');if(p.model)allowed.push('protected model updates');if(p.demographic)allowed.push('demographic ranges');if(p.individual)allowed.push('individual records');summary.innerHTML='Current administrator release policy: <b>'+esc(allowed.length?allowed.join(', '):'no release categories')+'</b>. Individual-level access remains '+(p.individual?'enabled by policy':'blocked')+'. Changes are made from Infrastructure and apply to new Analyst Console evaluations.'}

function healthLive(){if(file()!=='health.html')return;let box=document.getElementById('health-grid');if(!box)return;let s=state(),q=queries(),connected=s.custodians.filter(c=>c.connected).length,total=s.custodians.length,blocked=q.filter(x=>x.decision==='BLOCKED').length,events=s.events.length,pressure=s.custodians.reduce((a,c)=>a+c.budget,0);let links=total?Math.round(connected/total*100):0;let threat=blocked>=3?'REVIEW':blocked>0?'WATCH':'HEALTHY';let secure=Math.max(70,Math.min(100,connected?96:62));let privacy=Math.max(65,Math.min(100,Math.round(100-Math.min(30,(+s.eps||.6)*2))));let access=Math.max(55,100-Math.min(45,blocked*8));let threatScore=threat==='REVIEW'?72:threat==='WATCH'?88:97;let audit=Math.max(70,Math.min(100,90+Math.min(10,events)));let checks=[['Secure aggregator',connected?'Operational':'Degraded',secure],['Privacy engine','Operational',privacy],['Access control',blocked?'Monitor activity':'Operational',access],['Threat monitor',threat==='HEALTHY'?'Operational':'Review recent activity',threatScore],['Audit stream',events?'Receiving events':'Waiting for events',audit],['Hospital links',connected+'/'+total+' connected',links]];box.innerHTML=checks.map(x=>'<div class="card"><h3>'+x[0]+'</h3><p class="muted">'+x[1]+'</p><span class="tag '+(x[2]>=90?'green':'amber')+'">● '+(x[2]>=90?'HEALTHY':x[2]>=75?'MONITOR':'REVIEW')+'</span><div class="bar"><i style="width:'+x[2]+'%"></i></div><span class="muted">'+x[2]+'%</span></div>').join('');let c=document.getElementById('health-note');if(!c){c=document.createElement('div');c.id='health-note';c.className='card';c.style.marginTop='15px';box.parentElement.appendChild(c)}c.innerHTML='<h3>Recommended operational action</h3><p class="muted">'+(blocked>=3||pressure<1?'Controls need attention: review high-risk requests, inspect Threat Detection, and verify privacy-budget pressure before further sensitive analytics.':'System is healthy: maintain routine monitoring, validate policy changes periodically, and keep the demonstration state reproducible.')+'</p><p class="muted">Live state: '+connected+'/'+total+' custodians connected · '+blocked+' blocked requests · '+events+' audit/security events.</p>'}


function finalDynamicNormalization(){
 const f=file(),s=state();
 if(f==='hospitals.html'){
   const p=document.querySelector('main>p.muted');if(p)p.textContent=s.custodians.length+' protected government records custodians.';
 }
 if(f==='federated.html'){
   const p=document.querySelector('main>p.muted');if(p)p.textContent='Each connected establishment computes locally before protected aggregation.';
   const core=document.getElementById('fed-global');if(core)core.textContent='Global model v'+Number(s.modelVersion||1).toFixed(1);
 }
 if(f==='overview.html'||f==='index.html') updateGlobal();
 // Keep page state synchronized when another page/tab changes the control-plane state.
 if(!window.__ppaStateSync){window.__ppaStateSync=true;window.addEventListener('storage',()=>{if(location.pathname){setTimeout(()=>location.reload(),80)}})}
}

function boot(){setupNavigation();injectGuide();updateGlobal();dashboard();overviewEnh();prevalence();federated();pipeline();consoleEnh();decisions();attack();ledger();tradeoff();hospitals();policyEnh();threatEnh();differencing();monitorEnh();auditEnh();exports();healthLive();finalDynamicNormalization();maybeContext()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
